<?php require_once __DIR__.'/../auth.php'; require_admin();
$q=trim($_GET['q']??'');$course=trim($_GET['course']??'');$like='%'.$q.'%';
$s=$conn->prepare("SELECT student_id,name,email,mobile,course,year,gender,created_at FROM students WHERE (name LIKE ? OR email LIKE ?) AND (?='' OR course=?) ORDER BY created_at DESC");$s->bind_param('ssss',$like,$like,$course,$course);$s->execute();$rows=$s->get_result();page_start('Practical 11 — Student Management'); ?>
<p>Only administrators can manage student records.</p><form method="get"><label>Search name/email</label><input name="q" value="<?=e($q)?>" placeholder="Search students"><label>Filter course</label><select name="course"><option value="">All courses</option><?php foreach(['BCA','B.Tech','BBA','MCA'] as $c):?><option value="<?=e($c)?>" <?=$course===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><button>Search / Filter</button></form><p><a class="btn" href="edit.php">Add student</a></p>
<table><thead><tr><th>Name</th><th>Email</th><th>Mobile</th><th>Course</th><th>Year</th><th>Actions</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['mobile'])?></td><td><?=e($r['course'])?></td><td><?=e($r['year'])?></td><td><a class="btn" href="edit.php?id=<?=(int)$r['student_id']?>">Edit</a><form class="inline" method="post" action="delete.php" onsubmit="return confirm('Delete student record?')"><input type="hidden" name="id" value="<?=(int)$r['student_id']?>"><button class="danger">Delete</button></form></td></tr><?php endwhile;?></tbody></table><?php $s->close();page_end(); ?>
